import{_ as i,l as s,o as e,c as l,v as r,p as d,x as t,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"CIDR 与聚合","description":"","frontmatter":{"title":"CIDR 与聚合","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cidr-agg.md","filePath":"cs/cidr-agg.md","lastUpdated":1789023840000}'),A={name:"cs/cidr-agg.md"};function E(h,a,_,B,C,u){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="cidr-与聚合" tabindex="-1">CIDR 与聚合 <a class="header-anchor" href="#cidr-与聚合" aria-label="Permalink to &quot;CIDR 与聚合&quot;">​</a></h1><div class="epigraph"><p>前缀长度不再被三类地址锁死；相邻的一块可以在表里收成更短的一条，只要出口相同。</p><footer>—— 据 Fuller 等 CIDR；RFC 791 的地址仍是 32 位，分类被放弃</footer></div><p><a href="/cs/ip-subnet">上一课</a>给出 IPv4 地址与掩码：同一子网直连，跨网走路由器。本课不重算「主机位有几位」。缺口是分类编址把掩码钉成 /8、/16、/24，表项随机构爆炸，且不能把多块连续空间写成一条。CIDR：任意前缀长度，<strong>聚合</strong>把一簇更长前缀收成更短前缀。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RFC 791 的地址是 32 位；早期按首比特分成 A/B/C 类，路由器按类猜掩码。B 类太大、C 类太碎，核心表涨得比线路快。无类别域间路由让每条路由自带前缀长：<code>10.1.0.0/16</code> 覆盖其中所有 /24，若它们下一跳相同，只需一条。缺口是<strong>表的收缩规则</strong>，不是最长匹配怎么查——那是下一课。</p><p><span class="marginnote">聚合的前提是覆盖完整且策略相同。有一个 /24 要走另一出口，就必须把它作为更具体的例外留下，这正是后课 LPM 的输入。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路由通告带前缀与长度。聚合：若一组前缀构成某更短前缀的完全划分（或运维接受把空洞也收入），且出口一致，则只保留短前缀。主机接口仍用「地址 + 前缀长」判断直连，与分类无关。私网块（如 <code>10.0.0.0/8</code>）同样是 CIDR 前缀，后课 NAT 会用到。</p>',8)),(e(),d(p,null,{default:t(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLASS%5B%22A%2FB%2FC%20%E5%9B%BA%E5%AE%9A%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20EXP%5B%22%E8%A1%A8%E9%A1%B9%E8%86%A8%E8%83%80%22%5D%0A%20%20CIDR%5B%22%E4%BB%BB%E6%84%8F%E5%89%8D%E7%BC%80%E9%95%BF%22%5D%20--%3E%20AGG%5B%22%E7%9B%B8%E5%90%8C%E5%87%BA%E5%8F%A3%E5%88%99%E8%81%9A%E5%90%88%22%5D%0A%20%20AGG%20--%3E%20TAB%5B%22%E6%9B%B4%E7%9F%AD%E7%9A%84%E4%B8%80%E5%BC%A0%E8%A1%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CIDR 把「网络号」从类别改成（前缀，长度）对，使 <a href="/cs/arp">ARP</a> 的「是否同一链路」与核心转发表用同一种语言。聚合减少控制平面与 FIB 容量；数据平面转发仍是查表。端到端不变：前缀是定位与可达，不是文件完整性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 BGP 如何宣布聚合、何时带 ATOMIC_AGGREGATE 写完。也不引入 IPv6 的 /48 分配政策。查找冲突（长短前缀同时命中）下一课最长前缀匹配。</p><p>后课默认：表项是前缀，可以嵌套。嵌套时选哪一条，下一课 LPM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CIDR 让掩码任意；聚合用短前缀代替一簇长前缀。</li><li>分类编址不再是转发规则。</li><li>多条命中时如何选，下一课。</li><li>出处：CIDR（Fuller 等）；RFC 791；Kurose and Ross。</li></ul>',7))])}const f=i(A,[["render",E]]);export{D as __pageData,f as default};
